/**
 * @name Unsafe callback execution in plugin system
 * @description User-controlled input flowing to callback or hook execution could lead to arbitrary code execution
 * @kind path-problem
 * @problem.severity error
 * @id py/unsafe-callback-execution
 * @tags security
 *        external/cwe/cwe-094
 *        external/cwe/cwe-470
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.dataflow.new.RemoteFlowSources
import semmle.python.Concepts
import semmle.python.ApiGraphs

module UnsafeCallbackConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    source instanceof RemoteFlowSource
  }

  predicate isSink(DataFlow::Node sink) {
    // Look for calls to functions that execute callbacks
    exists(API::CallNode call |
      // Calls that might execute callbacks based on input
      call = API::moduleImport("pluggy").getMember(["_callers", "_manager", "_hooks"]).getACall() and
      (
        // Check for any argument that could be a callback
        sink = call.getArg(0) or
        sink = call.getArg(1) or
        sink = call.getArg(2)
      )
    )
    or
    // Direct calls to functions like getattr, setattr, etc. with user input
    exists(API::CallNode builtinCall |
      (
        builtinCall = API::builtin("getattr").getACall() or
        builtinCall = API::builtin("setattr").getACall() or
        builtinCall = API::builtin("hasattr").getACall() or
        builtinCall = API::builtin("callable").getACall()
      ) and
      sink = builtinCall.getArg(1) // Second argument is attribute name
    )
  }
}

module UnsafeCallbackFlow = TaintTracking::Global<UnsafeCallbackConfig>;
import UnsafeCallbackFlow::PathGraph

from UnsafeCallbackFlow::PathNode source, UnsafeCallbackFlow::PathNode sink
where UnsafeCallbackFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "Unsafe callback execution from $@.", source.getNode(), "user input"

/**
 * @name Unsafe dynamic plugin import in pluggy
 * @description Pluggy might dynamically import plugins based on user-controlled names
 * @kind path-problem
 * @problem.severity error
 * @id py/pluggy-unsafe-import
 * @tags security
 *        external/cwe/cwe-094
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.dataflow.new.RemoteFlowSources
import semmle.python.Concepts
import semmle.python.ApiGraphs

module PluggyImportConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    source instanceof RemoteFlowSource
  }

  predicate isSink(DataFlow::Node sink) {
    // Look for calls to import_module, __import__, or similar in pluggy context
    exists(API::CallNode call |
      (
        call = API::moduleImport("importlib").getMember("import_module").getACall() or
        call = API::builtin("__import__").getACall()
      ) and
      sink = call.getArg(0)
    )
  }
}

module PluggyImportFlow = TaintTracking::Global<PluggyImportConfig>;
import PluggyImportFlow::PathGraph

from PluggyImportFlow::PathNode source, PluggyImportFlow::PathNode sink
where PluggyImportFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "Unsafe dynamic plugin import from $@.", source.getNode(), "user input"

/**
 * @name Hook callback injection
 * @description User-controlled input being registered as hook callbacks could lead to arbitrary code execution
 * @kind path-problem
 * @problem.severity error
 * @id py/hook-callback-injection
 * @tags security
 *        external/cwe/cwe-094
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.dataflow.new.RemoteFlowSources
import semmle.python.Concepts
import semmle.python.ApiGraphs

module HookCallbackConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    source instanceof RemoteFlowSource
  }

  predicate isSink(DataFlow::Node sink) {
    // Look for calls to pluggy methods that register hooks/callbacks
    exists(API::CallNode hookCall |
      (
        // PluginManager.hook registration methods
        hookCall = API::moduleImport("pluggy").getMember("PluginManager").getASubclass*().getMember("hook").getACall() or
        hookCall = API::moduleImport("pluggy").getMember("PluginManager").getASubclass*().getMember("register").getACall() or
        hookCall = API::moduleImport("pluggy").getMember("PluginManager").getASubclass*().getMember("add_hookspecs").getACall() or
        hookCall = API::moduleImport("pluggy").getMember("PluginManager").getASubclass*().getMember("add_hookimpl").getACall()
      ) and
      sink = hookCall.getArg(0)  // First argument is often the callback/function
    )
    or
    exists(API::CallNode dictCall |
      // Dictionary assignment for hook callbacks
      dictCall = API::moduleImport("pluggy").getMember("PluginManager").getASubclass*().getMember("_hookimpls").getACall() and
      sink = dictCall.getArg(1)  // Value being assigned
    )
  }
}

module HookCallbackFlow = TaintTracking::Global<HookCallbackConfig>;
import HookCallbackFlow::PathGraph

from HookCallbackFlow::PathNode source, HookCallbackFlow::PathNode sink
where HookCallbackFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "Hook callback injection from $@.", source.getNode(), "user input"

/**
 * @name Insecure plugin method invocation
 * @description Calling plugin methods based on user input could lead to unauthorized access or privilege escalation
 * @kind path-problem
 * @problem.severity high
 * @id py/insecure-method-invocation
 * @tags security
 *        external/cwe/cwe-749
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.dataflow.new.RemoteFlowSources
import semmle.python.Concepts
import semmle.python.ApiGraphs

module MethodInvocationConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    source instanceof RemoteFlowSource
  }

  predicate isSink(DataFlow::Node sink) {
    exists(API::CallNode call |
      // Method calls via getattr or similar mechanisms
      call = API::builtin("getattr").getACall() and
      sink = call.getArg(1)
    )
  }
}

module MethodInvocationFlow = TaintTracking::Global<MethodInvocationConfig>;
import MethodInvocationFlow::PathGraph

from MethodInvocationFlow::PathNode source, MethodInvocationFlow::PathNode sink
where MethodInvocationFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "Insecure method invocation with user-controlled method name from $@.", source.getNode(), "user input"
